-- =====================================================================
-- ATIP -- atip_schema.postgresql.sql   (PostgreSQL 16; ATIP's server database)
--
-- GENERATED by tools/schema_sql.py from ATIP's own code (init_db() + seed_weights()
-- + ops.migrations.apply() + the tables created on first use). Do not edit by hand:
-- change the code and run `python tools/schema_sql.py`.
--
-- 250 tables, 112 indexes, 16 append-only triggers, and seed rows: schema_migrations (6), weight_config (105).
--
--   createdb atip
--   psql -d atip -v ON_ERROR_STOP=1 -f db/sql/atip_schema.postgresql.sql
--
-- Into an EMPTY database. Then switch ATIP over as docs/POSTGRESQL_MIGRATION.md
-- says (ATIP_DATABASE_URL + config.json "database": {"backend": "postgresql",
-- "allow_experimental": true}). To move EXISTING data use
-- tools/sqlite_to_postgres.py on a backup copy, not this file.
-- =====================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS accuracy_tracker (
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pred_date DATE NOT NULL, symbol TEXT NOT NULL,
        signal TEXT, entry_price DOUBLE PRECISION,
        price_5d DOUBLE PRECISION, return_5d DOUBLE PRECISION, correct_5d BIGINT,
        price_10d DOUBLE PRECISION, return_10d DOUBLE PRECISION, correct_10d BIGINT,
        price_20d DOUBLE PRECISION, return_20d DOUBLE PRECISION, correct_20d BIGINT,
        hit_target_1 BIGINT DEFAULT 0, hit_stop_loss BIGINT DEFAULT 0,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(pred_date,symbol));

CREATE TABLE IF NOT EXISTS ai_scores (
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, symbol TEXT NOT NULL, date DATE NOT NULL,
        vpi DOUBLE PRECISION, spi DOUBLE PRECISION, rri DOUBLE PRECISION, mri DOUBLE PRECISION, cri DOUBLE PRECISION, msi DOUBLE PRECISION, zpi DOUBLE PRECISION, acs DOUBLE PRECISION,
        tech_score DOUBLE PRECISION, fund_score DOUBLE PRECISION, inst_score DOUBLE PRECISION, news_score DOUBLE PRECISION,
        atip_score DOUBLE PRECISION, atip_rank BIGINT, signal TEXT, confidence DOUBLE PRECISION,
        beta_1y DOUBLE PRECISION,
        tod_score DOUBLE PRECISION, is_tod BIGINT DEFAULT 0,
        mh_score DOUBLE PRECISION, regime TEXT,
        top_factor_1 TEXT, top_factor_2 TEXT, top_factor_3 TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(symbol,date));

CREATE TABLE IF NOT EXISTS ai_usage_log (
            id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, day DATE NOT NULL, created_at TIMESTAMP, purpose TEXT, model TEXT,
            input_tokens BIGINT, output_tokens BIGINT, cache_write_tokens BIGINT, cache_read_tokens BIGINT,
            cost_usd DOUBLE PRECISION, ok BIGINT, error TEXT);

CREATE TABLE IF NOT EXISTS alert_log (
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP NOT NULL,
        category TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'info',
        title TEXT, message TEXT NOT NULL, dedupe_key TEXT,
        telegram_sent BIGINT NOT NULL DEFAULT 0, telegram_error TEXT);

CREATE TABLE IF NOT EXISTS alt_dataset (
            source_id TEXT PRIMARY KEY, name TEXT, description TEXT, entity TEXT, frequency TEXT, enabled BIGINT,
            last_run TIMESTAMP, last_status TEXT, last_rows BIGINT, coverage DOUBLE PRECISION, stale_days BIGINT, error TEXT,
            meta_json TEXT);

CREATE TABLE IF NOT EXISTS alt_observation (
            source_id TEXT NOT NULL, entity TEXT NOT NULL, date DATE NOT NULL, metric TEXT NOT NULL, value DOUBLE PRECISION,
            available_from TIMESTAMP, meta_json TEXT, PRIMARY KEY (source_id, entity, date, metric));

CREATE TABLE IF NOT EXISTS asset_price_daily (
            asset_class TEXT NOT NULL, symbol TEXT NOT NULL, date DATE NOT NULL, open DOUBLE PRECISION, high DOUBLE PRECISION, low DOUBLE PRECISION,
            close DOUBLE PRECISION, volume DOUBLE PRECISION, currency TEXT, source TEXT, PRIMARY KEY (asset_class, symbol, date));

CREATE TABLE IF NOT EXISTS assistant_conversation (
            conversation_id TEXT PRIMARY KEY, title TEXT, created_at TIMESTAMP, updated_at TIMESTAMP);

CREATE TABLE IF NOT EXISTS assistant_message (
            id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, conversation_id TEXT NOT NULL, asked_at TIMESTAMP, question TEXT,
            answer TEXT, mode TEXT, model TEXT, tools_json TEXT, cost_usd DOUBLE PRECISION);

CREATE TABLE IF NOT EXISTS audit_export (
            export_id TEXT PRIMARY KEY, source TEXT NOT NULL, first_id BIGINT, last_id BIGINT, rows BIGINT,
            path TEXT, offbox_path TEXT, sha256 TEXT, chain_ok BIGINT, created_at TIMESTAMP);

CREATE TABLE IF NOT EXISTS backtest_drawdown (
            run_id TEXT NOT NULL, seq BIGINT NOT NULL, peak_date DATE, trough_date DATE,
            recovery_date DATE, peak_equity DOUBLE PRECISION, trough_equity DOUBLE PRECISION, depth_pct DOUBLE PRECISION,
            duration_sessions BIGINT, recovery_sessions BIGINT, PRIMARY KEY (run_id, seq));

CREATE TABLE IF NOT EXISTS backtest_equity (
            run_id TEXT NOT NULL, date DATE NOT NULL, cash DOUBLE PRECISION, positions_value DOUBLE PRECISION, equity DOUBLE PRECISION,
            exposure_pct DOUBLE PRECISION, n_positions BIGINT, realized_cum DOUBLE PRECISION, unrealized DOUBLE PRECISION,
            daily_return DOUBLE PRECISION, peak_equity DOUBLE PRECISION, drawdown_pct DOUBLE PRECISION, futures_margin DOUBLE PRECISION, futures_notional DOUBLE PRECISION, PRIMARY KEY (run_id, date));

CREATE TABLE IF NOT EXISTS backtest_montecarlo (
            mc_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, method TEXT NOT NULL, n_sims BIGINT,
            seed BIGINT, params_json TEXT, results_json TEXT, created_at TIMESTAMP);

CREATE TABLE IF NOT EXISTS backtest_run (
            run_id TEXT PRIMARY KEY, parent_run_id TEXT, kind TEXT NOT NULL DEFAULT 'single',
            window_index BIGINT, strategy_id TEXT NOT NULL, strategy_version TEXT,
            period_label TEXT, start_date DATE, end_date DATE, data_source TEXT, timeframe TEXT,
            initial_capital DOUBLE PRECISION, params_json TEXT, config_json TEXT NOT NULL, config_hash TEXT,
            code_version TEXT, data_fingerprint_json TEXT, bias_report_json TEXT, metrics_json TEXT,
            summary_json TEXT, status TEXT NOT NULL DEFAULT 'CREATED', error TEXT,
            created_at TIMESTAMP, started_at TIMESTAMP, finished_at TIMESTAMP, tenant_id TEXT DEFAULT 'default');

CREATE TABLE IF NOT EXISTS backtest_trade (
            run_id TEXT NOT NULL, seq BIGINT NOT NULL, symbol TEXT NOT NULL,
            entry_date DATE, entry_price DOUBLE PRECISION, entry_ref_price DOUBLE PRECISION, qty BIGINT,
            exit_date DATE, exit_price DOUBLE PRECISION, exit_ref_price DOUBLE PRECISION, exit_reason TEXT,
            gross_pnl DOUBLE PRECISION, costs DOUBLE PRECISION, net_pnl DOUBLE PRECISION, return_pct DOUBLE PRECISION, holding_sessions BIGINT,
            entry_reason TEXT, partial BIGINT, adds BIGINT, instrument TEXT, direction TEXT, expiry DATE, lots BIGINT, lot_size BIGINT, leg BIGINT, rolled BIGINT, calendar_spread DOUBLE PRECISION, roll_cost DOUBLE PRECISION, PRIMARY KEY (run_id, seq));

CREATE TABLE IF NOT EXISTS broker_health_check (
            id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, checked_at TIMESTAMP NOT NULL, overall TEXT NOT NULL,
            in_session BIGINT, checks_json TEXT);

CREATE TABLE IF NOT EXISTS broker_import_run (
            run_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, owner_id TEXT NOT NULL, broker TEXT, kind TEXT,
            filename TEXT, rows_in BIGINT, added BIGINT, skipped BIGINT, errors BIGINT, created_at TIMESTAMP,
            detail_json TEXT);

CREATE TABLE IF NOT EXISTS bulk_deals (
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, symbol TEXT NOT NULL, date DATE NOT NULL,
        net_value_cr DOUBLE PRECISION, deal_count BIGINT DEFAULT 0, source TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(symbol,date));

CREATE TABLE IF NOT EXISTS compliance_result (
        run_id TEXT NOT NULL, check_id TEXT NOT NULL, title TEXT, status TEXT NOT NULL, detail TEXT,
        evidence_json TEXT, PRIMARY KEY (run_id, check_id));

CREATE TABLE IF NOT EXISTS compliance_run (
        run_id TEXT PRIMARY KEY, at TIMESTAMP NOT NULL, trigger TEXT, passed BIGINT, warned BIGINT,
        failed BIGINT, summary TEXT);

CREATE TABLE IF NOT EXISTS corporate_actions (
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, symbol TEXT NOT NULL, ex_date DATE NOT NULL,
        subject TEXT NOT NULL, kind TEXT, factor DOUBLE PRECISION,
        status TEXT NOT NULL DEFAULT 'pending', price_factor DOUBLE PRECISION,
        price_rows BIGINT, volume_rows BIGINT, note TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, reconciled_at TIMESTAMP,
        UNIQUE(symbol, ex_date, subject));

CREATE TABLE IF NOT EXISTS corporate_announcement (
            ann_id TEXT PRIMARY KEY, symbol TEXT NOT NULL, company TEXT, broadcast_at TIMESTAMP,
            subject TEXT, detail TEXT, attachment_url TEXT, category TEXT, event_type TEXT, tone DOUBLE PRECISION,
            importance TEXT, confidence DOUBLE PRECISION, summary TEXT, classifier TEXT, nlp_json TEXT, fetched_at TIMESTAMP);

CREATE TABLE IF NOT EXISTS data_quality (
            id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, date DATE NOT NULL, check_name TEXT NOT NULL,
            severity TEXT NOT NULL, failed BIGINT, checked BIGINT, score DOUBLE PRECISION,
            detail TEXT, run_at TIMESTAMP, UNIQUE(date, check_name));

CREATE TABLE IF NOT EXISTS depth20_snapshot (
        symbol TEXT NOT NULL, ts TIMESTAMP NOT NULL, mid DOUBLE PRECISION, spread_bp DOUBLE PRECISION, dwi DOUBLE PRECISION, imb_l1 DOUBLE PRECISION, imb_20 DOUBLE PRECISION,
        bid_qty DOUBLE PRECISION, ask_qty DOUBLE PRECISION, levels BIGINT, best_bid DOUBLE PRECISION, best_bid_qty DOUBLE PRECISION, best_ask DOUBLE PRECISION, best_ask_qty DOUBLE PRECISION,
        ofi_l1 DOUBLE PRECISION, ofi_ml DOUBLE PRECISION, ofi_depth DOUBLE PRECISION, ofi_updates BIGINT, PRIMARY KEY (symbol, ts));

CREATE TABLE IF NOT EXISTS derivatives_instrument (
            instrument_id TEXT PRIMARY KEY, underlying TEXT NOT NULL, instrument_type TEXT NOT NULL,
            expiry DATE, strike DOUBLE PRECISION, option_type TEXT, lot_size BIGINT, exchange TEXT, source TEXT,
            created_at TIMESTAMP);

CREATE TABLE IF NOT EXISTS derivatives_quote (
            instrument_id TEXT NOT NULL, date DATE NOT NULL, open DOUBLE PRECISION, high DOUBLE PRECISION, low DOUBLE PRECISION, close DOUBLE PRECISION,
            settle DOUBLE PRECISION, volume BIGINT, open_interest BIGINT, oi_change BIGINT, underlying_close DOUBLE PRECISION,
            source TEXT, created_at TIMESTAMP, PRIMARY KEY (instrument_id, date));

CREATE TABLE IF NOT EXISTS earnings_surprise (
        symbol TEXT NOT NULL, period_end DATE NOT NULL, quarter TEXT, known_on DATE, available_from TEXT,
        exact_date BIGINT, nature TEXT, eps_q DOUBLE PRECISION, eps_year_ago DOUBLE PRECISION, eps_sd DOUBLE PRECISION, sue DOUBLE PRECISION, sue_n BIGINT,
        sue_reason TEXT, revenue_cr DOUBLE PRECISION, revenue_year_ago DOUBLE PRECISION, revenue_sd DOUBLE PRECISION, sue_revenue DOUBLE PRECISION,
        sue_revenue_n BIGINT, sue_revenue_reason TEXT, ttm_eps DOUBLE PRECISION, ttm_growth_pct DOUBLE PRECISION, ttm_growth_prev_pct DOUBLE PRECISION,
        eps_trend TEXT, eps_trend_pts DOUBLE PRECISION, eps_trend_reason TEXT, computed_at TIMESTAMP,
        PRIMARY KEY (symbol, period_end));

CREATE TABLE IF NOT EXISTS enterprise_alert_rule (
