            feature TEXT, op TEXT, value DOUBLE PRECISION, status TEXT, last_value DOUBLE PRECISION, last_triggered_at TIMESTAMP,
            created_at TIMESTAMP);

CREATE TABLE IF NOT EXISTS enterprise_api_key (
