            error TEXT, created_at TIMESTAMP, updated_at TIMESTAMP, provider_payment_id TEXT, refunded_amount DOUBLE PRECISION);

CREATE TABLE IF NOT EXISTS enterprise_permission (permission TEXT PRIMARY KEY, description TEXT);

CREATE TABLE IF NOT EXISTS enterprise_plan (
            plan_id TEXT PRIMARY KEY, name TEXT, price_month DOUBLE PRECISION, currency TEXT, limits_json TEXT,
