            close DOUBLE PRECISION, settle DOUBLE PRECISION, prev_close DOUBLE PRECISION, oi DOUBLE PRECISION, oi_chg DOUBLE PRECISION, volume DOUBLE PRECISION, value DOUBLE PRECISION,
            underlying DOUBLE PRECISION, lot_size BIGINT, iv DOUBLE PRECISION,
