CREATE TABLE IF NOT EXISTS fo_participant_oi (
    date DATE NOT NULL, client_type TEXT NOT NULL, fut_idx_long DOUBLE PRECISION, fut_idx_short DOUBLE PRECISION, fut_stk_long DOUBLE PRECISION, fut_stk_short DOUBLE PRECISION, opt_idx_call_long DOUBLE PRECISION, opt_idx_put_long DOUBLE PRECISION, opt_idx_call_short DOUBLE PRECISION, opt_idx_put_short DOUBLE PRECISION, opt_stk_call_long DOUBLE PRECISION, opt_stk_put_long DOUBLE PRECISION, opt_stk_call_short DOUBLE PRECISION, opt_stk_put_short DOUBLE PRECISION, total_long DOUBLE PRECISION, total_short DOUBLE PRECISION, fetched_at TIMESTAMP, PRIMARY KEY (date, client_type));

CREATE TABLE IF NOT EXISTS fo_underlying_daily (
