            call_oi DOUBLE PRECISION, put_oi DOUBLE PRECISION, call_oi_chg DOUBLE PRECISION, put_oi_chg DOUBLE PRECISION, call_volume DOUBLE PRECISION, put_volume DOUBLE PRECISION,
            pcr_oi DOUBLE PRECISION, pcr_volume DOUBLE PRECISION, max_pain DOUBLE PRECISION, near_expiry DATE, created_at TIMESTAMP, atm_iv DOUBLE PRECISION, iv_call_atm DOUBLE PRECISION, iv_put_atm DOUBLE PRECISION, iv_skew DOUBLE PRECISION, iv_expiry DATE, iv_dte BIGINT, lot_size BIGINT,
