        profit_cr DOUBLE PRECISION, profit_growth_yoy DOUBLE PRECISION, qoq_revenue_chg DOUBLE PRECISION, qoq_profit_chg DOUBLE PRECISION,
        debt_equity DOUBLE PRECISION, current_ratio DOUBLE PRECISION, interest_coverage DOUBLE PRECISION, fcf_cr DOUBLE PRECISION, cash_cr DOUBLE PRECISION,
        pe_ratio DOUBLE PRECISION, pb_ratio DOUBLE PRECISION, ev_ebitda DOUBLE PRECISION, peg_ratio DOUBLE PRECISION, dividend_yield DOUBLE PRECISION,
        book_value_ps DOUBLE PRECISION, promoter_hold DOUBLE PRECISION, promoter_pledge DOUBLE PRECISION, inst_hold DOUBLE PRECISION,
