        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, period_end DATE, available_from TIMESTAMP, nature TEXT, eps_q DOUBLE PRECISION, spi_score DOUBLE PRECISION, score_inputs TEXT, mf_hold DOUBLE PRECISION, fpi_hold DOUBLE PRECISION, shares_out DOUBLE PRECISION, equity_cr DOUBLE PRECISION, debt_cr DOUBLE PRECISION, profit_fy_cr DOUBLE PRECISION, UNIQUE(symbol,quarter));

