        sp500 DOUBLE PRECISION, sp500_chg DOUBLE PRECISION, dow DOUBLE PRECISION, dow_chg DOUBLE PRECISION, nasdaq DOUBLE PRECISION, nasdaq_chg DOUBLE PRECISION,
