CREATE OR REPLACE FUNCTION atip_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '%', TG_ARGV[0]; END $$;

CREATE TRIGGER trg_ent_audit_no_delete BEFORE DELETE ON enterprise_audit FOR EACH ROW EXECUTE FUNCTION atip_append_only('enterprise_audit is append-only');

CREATE TRIGGER trg_ent_audit_no_update BEFORE UPDATE ON enterprise_audit FOR EACH ROW EXECUTE FUNCTION atip_append_only('enterprise_audit is append-only');

CREATE TRIGGER trg_investor_profile_version_no_delete BEFORE DELETE ON investor_profile_version FOR EACH ROW WHEN (OLD.tenant_id <> 'uat') EXECUTE FUNCTION atip_append_only('investor_profile_version is append-only');

CREATE TRIGGER trg_investor_profile_version_no_update BEFORE UPDATE ON investor_profile_version FOR EACH ROW EXECUTE FUNCTION atip_append_only('investor_profile_version is append-only');

